def solution() -> int:
    W = [9, 5]
    V = [17, 8]
    C = 2

    # Initialize a DP table where dp[i][w] represents the maximum value achievable with the first i items and capacity w
    dp = [[0 for _ in range(C + 1)] for _ in range(len(W) + 1)]

    for i in range(1, len(W) + 1):
        for w in range(C + 1):
            if W[i - 1] <= w:
                dp[i][w] = max(dp[i - 1][w], dp[i - 1][w - W[i - 1]] + V[i - 1])
            else:
                dp[i][w] = dp[i - 1][w]

    return dp[len(W)][C]

