from scipy.optimize import linear_sum_assignment

def solution() -> int:
    C = [[9, 5], [17, 8]]
    row_ind, col_ind = linear_sum_assignment(C)
    total_cost = C[row_ind[0]][col_ind[0]] + C[row_ind[1]][col_ind[1]]
    return int(total_cost)

from typing import Dict, List

def solution() -> Dict[int, List[int]]:
    # Input data: participants and their available slots
    participants = {
        0: {'available_slots': [0, 1, 3], 'meetings': [0]},
        1: {'available_slots': [0, 1, 2, 3], 'meetings': [1, 0]},
        2: {'available_slots': [0, 1, 2, 3], 'meetings': [0]}
    }

    # Find the common available slot among all participants
    common_slots = set(participants[0]['available_slots'])
    for participant in participants.values():
        common_slots.intersection_update(participants[participant]['available_slots'])

    # If no common slot, return empty dict (no solution)
    if not common_slots:
        return {}

    # Select the first common slot (e.g., 1) as the meeting time
    meeting_time = min(common_slots)

    # Assign the meeting time to all participants
    result = {participant: [meeting_time] for participant in participants}

    return result

