def solution() -> int:
    sorted_array = [6, 13, 14]
    target = 6

    left, right = 0, len(sorted_array) - 1

    while left <= right:
        mid = (left + right) // 2
        if sorted_array[mid] == target:
            return mid
        elif sorted_array[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1  # Target not found (though in this case, it exists)

